import React, { useEffect, useState, useCallback } from 'react';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer
} from 'recharts';
import { Brain, AlertTriangle, RefreshCw, Info } from 'lucide-react';
import { clinicalService } from '../services/api';

const DISCLAIMER = (
  "⚠ RESEARCH / DEMONSTRATION ONLY — This score is generated by a model trained on " +
  "synthetic data. It is NOT clinically validated and must NOT be used for clinical decisions."
);

const riskStyle = {
  LOW:    { color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/30', bar: '#10b981' },
  MEDIUM: { color: 'text-amber-400',   bg: 'bg-amber-500/10',   border: 'border-amber-500/30',   bar: '#f59e0b' },
  HIGH:   { color: 'text-rose-400',    bg: 'bg-rose-500/10',    border: 'border-rose-500/30',     bar: '#f43f5e' },
};

export default function RiskDashboard({ patientId }) {
  const [risk, setRisk] = useState(null);
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [modelReady, setModelReady] = useState(null);

  const fetchRisk = useCallback(async () => {
    if (!patientId) return;
    setLoading(true);
    setError(null);
    try {
      const [statusRes, riskRes, histRes] = await Promise.allSettled([
        clinicalService.getMLStatus(),
        clinicalService.getPatientRisk(patientId),
        clinicalService.getRiskHistory(patientId),
      ]);

      if (statusRes.status === 'fulfilled') {
        setModelReady(statusRes.value.data.model_ready);
      }
      if (riskRes.status === 'fulfilled' && riskRes.value.data.success) {
        setRisk(riskRes.value.data);
      } else if (riskRes.status === 'rejected') {
        const msg = riskRes.reason?.response?.data?.error || 'Failed to fetch risk score';
        setError(msg);
      }
      if (histRes.status === 'fulfilled') {
        const raw = histRes.value.data.data || [];
        setHistory(
          raw
            .slice(0, 20)
            .reverse()
            .map((r, i) => ({
              label: `T-${raw.slice(0, 20).length - i}`,
              risk: r.risk_score != null ? parseFloat((r.risk_score * 100).toFixed(1)) : null,
              category: r.risk_category,
            }))
        );
      }
    } catch {
      setError('Risk service unavailable.');
    } finally {
      setLoading(false);
    }
  }, [patientId]);

  useEffect(() => {
    fetchRisk();
  }, [fetchRisk]);

  if (!patientId) return null;

  const st = risk ? (riskStyle[risk.risk_category] || riskStyle.MEDIUM) : null;

  return (
    <div className="bg-slate-900 border border-slate-800 rounded-xl p-5 space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Brain className="w-4 h-4 text-violet-400" />
          <h3 className="text-sm font-semibold text-slate-300 uppercase tracking-wider">
            AI Early Warning
          </h3>
          <span className="text-xs px-2 py-0.5 rounded-full bg-violet-500/10 border border-violet-500/20 text-violet-400">
            DEMO
          </span>
        </div>
        <button
          onClick={fetchRisk}
          disabled={loading}
          className="p-1.5 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-white transition-colors"
          title="Refresh risk score"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      {/* Disclaimer */}
      <div className="flex items-start gap-2 p-3 bg-amber-500/5 border border-amber-500/20 rounded-lg">
        <Info className="w-3.5 h-3.5 text-amber-400 shrink-0 mt-0.5" />
        <p className="text-xs text-amber-300/80 leading-relaxed">{DISCLAIMER}</p>
      </div>

      {/* Loading */}
      {loading && (
        <div className="flex items-center justify-center py-8 text-slate-500">
          <RefreshCw className="w-4 h-4 animate-spin mr-2" />
          <span className="text-sm">Computing experimental risk…</span>
        </div>
      )}

      {/* Model not ready */}
      {!loading && modelReady === false && (
        <div className="text-center py-6">
          <Brain className="w-8 h-8 mx-auto mb-2 text-slate-600" />
          <p className="text-sm text-slate-400">Model not trained yet.</p>
          <p className="text-xs text-slate-500 mt-1">
            POST <code>/api/v1/ml/train</code> to train the demo model.
          </p>
        </div>
      )}

      {/* Error */}
      {!loading && error && modelReady !== false && (
        <div className="flex items-center gap-2 p-3 bg-rose-500/10 border border-rose-500/20 rounded-lg text-rose-400">
          <AlertTriangle className="w-4 h-4 shrink-0" />
          <p className="text-sm">{error}</p>
        </div>
      )}

      {/* Risk Score */}
      {!loading && risk && st && (
        <>
          <div className={`flex items-center gap-4 p-4 ${st.bg} border ${st.border} rounded-xl`}>
            {/* Gauge */}
            <div className="relative w-20 h-20 shrink-0">
              <svg viewBox="0 0 36 36" className="w-full h-full -rotate-90">
                <circle cx="18" cy="18" r="15.9" fill="none" stroke="#1e293b" strokeWidth="3" />
                <circle
                  cx="18" cy="18" r="15.9"
                  fill="none"
                  stroke={st.bar}
                  strokeWidth="3"
                  strokeDasharray={`${risk.experimental_risk_score} ${100 - risk.experimental_risk_score}`}
                  strokeLinecap="round"
                />
              </svg>
              <div className="absolute inset-0 flex items-center justify-center">
                <span className={`text-lg font-bold font-mono ${st.color}`}>
                  {risk.experimental_risk_score}
                </span>
              </div>
            </div>

            <div>
              <p className={`text-xl font-bold ${st.color}`}>{risk.risk_category}</p>
              <p className="text-xs text-slate-400 mt-0.5">Experimental Risk Category</p>
              <p className="text-xs text-slate-500 mt-2">
                Model: v{risk.model_version}
              </p>
              <p className="text-xs text-slate-500">
                Assessed: {risk.assessed_at ? new Date(risk.assessed_at).toLocaleTimeString() : '—'}
              </p>
              <p className="text-xs text-slate-500">
                Window: {risk.vitals_window_size} readings
              </p>
            </div>
          </div>

          {/* History chart */}
          {history.length > 1 && (
            <div>
              <p className="text-xs text-slate-500 mb-2 uppercase tracking-wider">Historical Risk Trend</p>
              <ResponsiveContainer width="100%" height={120}>
                <LineChart data={history} margin={{ top: 4, right: 10, bottom: 0, left: -20 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                  <XAxis dataKey="label" tick={{ fill: '#475569', fontSize: 10 }} />
                  <YAxis domain={[0, 100]} tick={{ fill: '#475569', fontSize: 10 }} />
                  <Tooltip
                    contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: 8 }}
                    labelStyle={{ color: '#94a3b8' }}
                    itemStyle={{ color: '#e2e8f0' }}
                    formatter={(v) => [`${v}/100`, 'Exp. Risk Score']}
                  />
                  <Line
                    type="monotone" dataKey="risk"
                    stroke="#8b5cf6" strokeWidth={2} dot={false}
                    name="Exp. Risk"
                    connectNulls
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          )}
        </>
      )}
    </div>
  );
}
